ps: function(pid, options, done) {

  pid = parseInt(pid, 10)

  if(isNaN(pid) || pid < 0)
    return done(new TypeError('pid must be a positive integer'), null)

  var args = ['-o', 'pcpu,rss', '-p', String(pid)]

  if(os.platform() == 'aix')
    args = ['-o', 'pcpu,rssize', '-p', String(pid)] //this one could work on other platforms

  var ps = spawn('ps', args)
  var stdout = ''
  var stderr = ''

  ps.stdout.on('data', function(d) {
    stdout += d.toString()
  })

  ps.stderr.on('data', function(d) {
    stderr += d.toString()
  })

  ps.on('close', function(code) {
    if(code !== 0)
      return done(new Error(stderr || 'ps exited with code ' + code), null)

    stdout = stdout.split(os.EOL)[1]
    stdout = stdout.replace(/^\s+/, '').replace(/\s\s+/g, ' ').split(' ')

    return done(null, {
      cpu: parseFloat(stdout[0].replace(',', '.')),
      memory: parseFloat(stdout[1]) * 1024
    })
  })
},

